import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, uniform, abs, max, length, MathUtils } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Color } = ctx.THREE;

  // Root container for this element
  const container = new Group();
  container.position.set(1.25, 0.7, 0);

  // Active GSAP timelines to kill in cleanup
  const activeTimelines = [];

  // Theme colors
  const colors = {
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
    accent: new Color('#ff2a38'),
    surface: new Color('#0b0b10')
  };

  // 1. Stage Backdrop (to avoid FLAT_VOID and ground the element)
  const backdropGeo = new PlaneGeometry(8, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const topColor = vec3(colors.surface.r * 0.4, colors.surface.g * 0.4, colors.surface.b * 0.4);
  const bottomColor = vec3(colors.ink.r * 0.2, colors.ink.g * 0.2, colors.ink.b * 0.2);
  backdropMat.colorNode = mix(bottomColor, topColor, uv().y);
  backdropMat.depthWrite = false;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  container.add(backdrop);

  // Contact shadow under the capsule
  const shadowGeo = new PlaneGeometry(1.6, 0.4);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  const shadowDist = length(uv().sub(0.5).mul(vec2(2.0, 4.0)));
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = smoothstep(0.8, 0.0, shadowDist).mul(0.5);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.35, -0.05);
  container.add(shadow);

  // 2. Interactive Capsule Badge Mesh
  const badgeWidth = 1.4;
  const badgeHeight = 0.45;
  const badgeGeo = new PlaneGeometry(badgeWidth, badgeHeight);

  // Interactive uniforms for shader effects
  const accentGlow = uniform(0.2); // Glow intensity, increases on hover
  const pulseTime = uniform(0.0);

  const badgeMat = new MeshStandardNodeMaterial({
    metalness: 0.5,
    roughness: 0.6,
    transparent: true
  });

  // Load the ceramic-grain texture from assets
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.wrapS = 1000; // Repeat Wrapping
      texture.wrapT = 1000;
      badgeMat.map = texture;
      badgeMat.needsUpdate = true;
    });
  }

  // Capsule SDF logic for the edge lighting
  const sdfSize = vec2(0.5, 0.1);
  const sdfRadius = 0.12;
  const p = uv().sub(0.5).mul(vec2(badgeWidth, badgeHeight));
  const d = length(max(abs(p).sub(sdfSize), 0.0)).sub(sdfRadius);

  // Mask defines the shape of the boundary
  const insideMask = smoothstep(0.005, -0.005, d);
  const borderMask = smoothstep(0.005, -0.005, abs(d.add(0.015))).sub(smoothstep(0.005, -0.005, d));

  // Base background & edge illumination mix
  const baseFill = vec3(colors.surface.r, colors.surface.g, colors.surface.b);
  const edgeColor = vec3(colors.accent.r, colors.accent.g, colors.accent.b);

  // Blend normal state and hover edge lighting
  const finalEdgeColor = mix(edgeColor, vec3(colors.paper.r, colors.paper.g, colors.paper.b), pulseTime.mul(0.3));
  const compoundColor = mix(baseFill, finalEdgeColor.mul(accentGlow.mul(3.0)), borderMask);

  badgeMat.colorNode = compoundColor;
  badgeMat.opacityNode = insideMask;

  const badgeMesh = new Mesh(badgeGeo, badgeMat);
  container.add(badgeMesh);

  // 3. Typography Label (Using ASCII only)
  const textContentItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelText = textContentItems[0]?.text ?? 'ACCESS';

  const textObj = ctx.fontAtlas.createText(labelText.toUpperCase(), {
    fontSize: 0.09,
    color: colors.paper.getHexString(),
    align: 'center',
    letterSpacingPx: 3
  });
  textObj.position.set(0, -0.03, 0.02); // Positioned slightly proud of the badge surface
  badgeMesh.add(textObj);

  // 4. Interaction Orchestration (GSAP)
  let isHovered = false;

  const handlePointerOver = () => {
    isHovered = true;
    // Animate shader edge emission
    gsap.to(accentGlow, { value: 1.0, duration: 0.3, overwrite: 'auto' });

    // Subtly pulse the border highlight
    gsap.to(pulseTime, { value: 1.0, duration: 0.6, repeat: -1, yoyo: true, ease: 'power1.inOut' });

    // Rise-in effect (0.15 scene units lift)
    gsap.to(badgeMesh.position, {
      y: 0.15,
      z: 0.1,
      duration: 0.35,
      ease: 'power2.out',
      overwrite: 'auto'
    });
    gsap.to(shadow.scale, {
      x: 1.15,
      y: 1.15,
      duration: 0.35,
      ease: 'power2.out',
      overwrite: 'auto'
    });
  };

  const handlePointerOut = () => {
    isHovered = false;
    gsap.to(accentGlow, { value: 0.2, duration: 0.4, overwrite: 'auto' });
    gsap.to(pulseTime, { value: 0.0, duration: 0.4, overwrite: 'auto' });

    // Return to rest
    gsap.to(badgeMesh.position, {
      y: 0,
      z: 0,
      duration: 0.45,
      ease: 'power3.out',
      overwrite: 'auto'
    });
    gsap.to(shadow.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.45,
      ease: 'power3.out',
      overwrite: 'auto'
    });
  };

  const handlePointerDown = () => {
    // Press-down response
    gsap.to(badgeMesh.scale, {
      x: 0.93,
      y: 0.93,
      duration: 0.1,
      ease: 'power2.out',
      yoyo: true,
      repeat: 1
    });

    // Emit target semantic configuration event
    ctx.emit('hub-pricing.select', { id: 'pricing-badge-select', label: labelText });
  };

  // Assign internal handler references
  badgeMesh.userData.handlers = {
    pointerover: handlePointerOver,
    pointerout: handlePointerOut,
    pointerdown: handlePointerDown
  };

  // Apply cinematic primitives (if any assigned in container pipeline)
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const pInstance = ctx.primitives[prim.name](badgeMesh, prim.params);
        if (pInstance && pInstance.cleanup) {
          activeTimelines.push(pInstance);
        }
      }
    });
  }

  // 5. Cleanup Handlers
  container.userData.cleanup = () => {
    badgeGeo.dispose();
    badgeMat.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    // Terminate all GSAP dynamics
    gsap.killTweensOf(accentGlow);
    gsap.killTweensOf(pulseTime);
    gsap.killTweensOf(badgeMesh.position);
    gsap.killTweensOf(badgeMesh.scale);
    gsap.killTweensOf(shadow.scale);

    activeTimelines.forEach((p) => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });
  };

  return container;
}
